import math

def is_power_of_two(n):
    """Checks if a positive integer n is a power of two."""
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

def get_exponent(n):
    """Returns k such that 2^k = n, assuming n is a power of two."""
    return int(math.log2(n))

n = 4
start_x = n + 1
end_x = 20
solutions = []

print(f"Testing n={n} for x from {start_x} to {end_x}:")

for x in range(start_x, end_x + 1):
    # Check if x^n + x - 2 is a power of 2.
    # We calculate M = x^n + x - 2
    try:
        M = x**n + x - 2
    except OverflowError:
        # Should not happen for x <= 20 and n=4, but good practice.
        print(f"Skipping x={x} due to overflow.")
        continue

    if is_power_of_two(M):
        k = get_exponent(M)
        solutions.append((x, n, k))
        print(f"Found solution: x={x}, n={n}, k={k}. M = {M}")
    # else:
    #     print(f"x={x}, M={M} is not a power of 2.")

print("\n--- Final Results ---")
if solutions:
    for sol in solutions:
        print(f"Tuple: {sol}")
else:
    print("No solutions found in the specified range.")

def check_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

found_solutions = []
for x in range(6, 21):
    n = 5
    value = x**n + x - 2
    if check_power_of_two(value):
        # Calculate k if it is a power of two
        k = value.bit_length() - 1
        found_solutions.append((x, n, k))

print(found_solutions)
